document$.subscribe(()=>{var button=document.getElementById("gridToggle");const photoElements=document.querySelectorAll(".photo");var flexBasisValue="calc(50% - 4px)";if(button){button.addEventListener("click",function(){if(flexBasisValue==="calc(50% - 4px)"){flexBasisValue="auto"}else{flexBasisValue="calc(50% - 4px)"}photoElements.forEach(imgElement=>{imgElement.style.flexBasis=flexBasisValue})})}var lazyLoadInstance=new LazyLoad({elements_selector:"img[data-lazy-src]",data_src:"lazy-src",data_srcset:"lazy-srcset",threshold:800,callback_loaded:function(el){el.classList.add("loaded");el.style.backgroundImage=""}});lazyLoadInstance.update();var travel=document.getElementsByClassName("travel-div");if(travel.length>0){var initCarousel=function(){var items=document.querySelectorAll(".carousel-item");if(!items.length)return;var total=items.length;var current=0;items.forEach(function(el,i){el.classList.toggle("active",i===0)});function setSlide(prev,next){var slide=next;if(next>total-1){slide=0;current=0}if(next<0){slide=total-1;current=total-1}items[prev].classList.remove("active");items[slide].classList.add("active")}var moveRight=document.getElementById("moveRight");var moveLeft=document.getElementById("moveLeft");if(moveRight){moveRight.onclick=function(){var prev=current;current=current+1;setSlide(prev,current)}}if(moveLeft){moveLeft.onclick=function(){var prev=current;current=current-1;setSlide(prev,current)}}};initCarousel()}if(typeof lightbox!=="undefined"){lightbox.reload()}});
